from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def generate_parenthesis(n: int) -> list[str]:
    out: list[str] = []
    path: list[str] = []

    def dfs(opened: int, closed: int) -> None:
        if len(path) == 2 * n:
            out.append("".join(path))
            return
        if opened < n:
            path.append("(")
            dfs(opened + 1, closed)
            path.pop()
        if closed < opened:
            path.append(")")
            dfs(opened, closed + 1)
            path.pop()

    dfs(0, 0)
    return sorted(out)

